SHARE_SUM_SQL = """
CREATE FUNCTION app.assert_expense_shares_sum(p_expense_id uuid) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
    v_amount bigint;
    v_sum bigint;
    v_wrong_sign int;
BEGIN
    SELECT amount_cents INTO v_amount FROM app.expenses WHERE id = p_expense_id;
    IF NOT FOUND THEN
        RETURN;  -- expense removed in the same transaction
    END IF;
    SELECT coalesce(sum(amount_cents), 0),
           count(*) FILTER (WHERE sign(amount_cents) = -sign(v_amount))
      INTO v_sum, v_wrong_sign
      FROM app.expense_shares WHERE expense_id = p_expense_id;
    IF v_sum <> v_amount THEN
        RAISE EXCEPTION 'expense % shares sum % does not match amount %', p_expense_id, v_sum, v_amount
            USING ERRCODE = 'check_violation', CONSTRAINT = 'expense_shares_sum';
    END IF;
    IF v_wrong_sign > 0 THEN
        RAISE EXCEPTION 'expense % has shares with the opposite sign of its amount', p_expense_id
            USING ERRCODE = 'check_violation', CONSTRAINT = 'expense_shares_sign';
    END IF;
END $$;

CREATE FUNCTION app.trg_expense_shares_sum() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_TABLE_NAME = 'expenses' THEN
        PERFORM app.assert_expense_shares_sum(NEW.id);
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM app.assert_expense_shares_sum(OLD.expense_id);
    ELSE
        PERFORM app.assert_expense_shares_sum(NEW.expense_id);
        IF TG_OP = 'UPDATE' AND OLD.expense_id <> NEW.expense_id THEN
            PERFORM app.assert_expense_shares_sum(OLD.expense_id);
        END IF;
    END IF;
    RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER expense_shares_sum
    AFTER INSERT OR UPDATE OR DELETE ON app.expense_shares
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION app.trg_expense_shares_sum();

CREATE CONSTRAINT TRIGGER expenses_shares_sum
    AFTER INSERT OR UPDATE OF amount_cents ON app.expenses
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION app.trg_expense_shares_sum();

CREATE FUNCTION app.assert_quick_expense_shares_sum(p_expense_id uuid) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
    v_amount bigint;
    v_sum bigint;
BEGIN
    SELECT amount_cents INTO v_amount FROM app.quick_expenses WHERE id = p_expense_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;
    SELECT coalesce(sum(amount_cents), 0) INTO v_sum
      FROM app.quick_expense_shares WHERE quick_expense_id = p_expense_id;
    IF v_sum <> v_amount THEN
        RAISE EXCEPTION 'quick expense % shares sum % does not match amount %', p_expense_id, v_sum, v_amount
            USING ERRCODE = 'check_violation', CONSTRAINT = 'quick_expense_shares_sum';
    END IF;
END $$;

CREATE FUNCTION app.trg_quick_expense_shares_sum() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_TABLE_NAME = 'quick_expenses' THEN
        PERFORM app.assert_quick_expense_shares_sum(NEW.id);
    ELSIF TG_OP = 'DELETE' THEN
        PERFORM app.assert_quick_expense_shares_sum(OLD.quick_expense_id);
    ELSE
        PERFORM app.assert_quick_expense_shares_sum(NEW.quick_expense_id);
    END IF;
    RETURN NULL;
END $$;

CREATE CONSTRAINT TRIGGER quick_expense_shares_sum
    AFTER INSERT OR UPDATE OR DELETE ON app.quick_expense_shares
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION app.trg_quick_expense_shares_sum();

CREATE CONSTRAINT TRIGGER quick_expenses_shares_sum
    AFTER INSERT OR UPDATE OF amount_cents ON app.quick_expenses
    DEFERRABLE INITIALLY DEFERRED
    FOR EACH ROW EXECUTE FUNCTION app.trg_quick_expense_shares_sum();
"""

APPEND_ONLY_SQL = """
CREATE FUNCTION app.trg_expense_revisions_append_only() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    RAISE EXCEPTION 'expense_revisions is append-only' USING ERRCODE = 'insufficient_privilege';
END $$;

CREATE TRIGGER expense_revisions_append_only
    BEFORE UPDATE ON app.expense_revisions
    FOR EACH ROW EXECUTE FUNCTION app.trg_expense_revisions_append_only();

CREATE FUNCTION app.trg_settlement_snapshots_immutable() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF (to_jsonb(NEW) - 'superseded_at') <> (to_jsonb(OLD) - 'superseded_at') THEN
        RAISE EXCEPTION 'settlement_snapshots are immutable except superseded_at'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER settlement_snapshots_immutable
    BEFORE UPDATE ON app.settlement_snapshots
    FOR EACH ROW EXECUTE FUNCTION app.trg_settlement_snapshots_immutable();
"""

# The runtime role is created by infra (it needs a password); grant only if it exists.
GRANTS_SQL = """
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'split_api') THEN
        GRANT USAGE ON SCHEMA app TO split_api;
        GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA app TO split_api;
        GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA app TO split_api;
        GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA app TO split_api;
        REVOKE UPDATE, DELETE ON app.expense_revisions FROM split_api;
        REVOKE DELETE ON app.settlement_snapshots FROM split_api;
    END IF;
END $$;
"""


def initial_post_upgrade() -> None:
    op.execute(SHARE_SUM_SQL)
    op.execute(APPEND_ONLY_SQL)
    # Defence in depth: RLS enabled with no policies, so anon/authenticated read nothing.
    for table in APP_TABLES:
        op.execute(f"ALTER TABLE app.{table} ENABLE ROW LEVEL SECURITY")
    op.execute(GRANTS_SQL)


def initial_pre_downgrade() -> None:
    for trigger, table in (
        ("expense_shares_sum", "expense_shares"),
        ("expenses_shares_sum", "expenses"),
        ("quick_expense_shares_sum", "quick_expense_shares"),
        ("quick_expenses_shares_sum", "quick_expenses"),
        ("expense_revisions_append_only", "expense_revisions"),
        ("settlement_snapshots_immutable", "settlement_snapshots"),
    ):
        op.execute(f"DROP TRIGGER IF EXISTS {trigger} ON app.{table}")
    for function in (
        "trg_expense_shares_sum()",
        "assert_expense_shares_sum(uuid)",
        "trg_quick_expense_shares_sum()",
        "assert_quick_expense_shares_sum(uuid)",
        "trg_expense_revisions_append_only()",
        "trg_settlement_snapshots_immutable()",
    ):
        op.execute(f"DROP FUNCTION IF EXISTS app.{function}")
